// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    PENNY_BY_PENNY c;
    function setUp() public { c = new PENNY_BY_PENNY(); }
    function testFuzz_property(address newLog) public {
        vm.assume(newLog != address(0));
        c.Initialized();
        bool ok;
        try c.SetLogFile(newLog) { ok = true; } catch { ok = false; }
        assertTrue(!ok, "SetLogFile should revert after initialization");
    }
}
